--
-- Table structure for table `mastermapping`
--

DROP TABLE IF EXISTS `mastermapping`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mastermapping` (
  `id` int NOT NULL AUTO_INCREMENT,
  `company_id` int NOT NULL,
  `product_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `masters_category` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `masters_category_id` tinyint NOT NULL,
  `field_name` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `ledger_id` int NOT NULL,
  `ledger_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `effective_from` date NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_master_mapping_field` (`company_id`,`product_type`,`field_name`),
  KEY `fk_master_mapping_ledger` (`ledger_id`),
  KEY `ix_master_mapping_company_product` (`company_id`,`product_type`,`masters_category`),
  CONSTRAINT `fk_master_mapping_ledger` FOREIGN KEY (`ledger_id`) REFERENCES `ledgers` (`id`),
  CONSTRAINT `ck_master_mapping_masters_category` CHECK ((`masters_category` in (_utf8mb4'Earnings From Customer',_utf8mb4'Earnings From Supplier',_utf8mb4'Expenditure To Customer',_utf8mb4'Expenditure To Supplier',_utf8mb4'GST and TDS'))),
