-- Table structure for table `ssr_al_ticketlines`
--

DROP TABLE IF EXISTS `ssr_al_ticketlines`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ssr_al_ticketlines` (
  `id` int NOT NULL AUTO_INCREMENT,
  `ticket_no` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `passenger_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pax_type` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `airline_category` varchar(5) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sector` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `office_id` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fop` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ssr_items` longtext COLLATE utf8mb4_unicode_ci,
