DROP TABLE IF EXISTS `vouchertype`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `vouchertype` (
  `id` int NOT NULL AUTO_INCREMENT,
  `company_id` int NOT NULL DEFAULT '1',
  `name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `alias_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `voucher_category` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `number_method` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `allow_additional_numbering` tinyint(1) NOT NULL DEFAULT '0',
  `allow_effective_dates` tinyint(1) NOT NULL DEFAULT '0',
  `allow_zero_value_transaction` tinyint(1) NOT NULL DEFAULT '0',
  `allow_narration` tinyint(1) NOT NULL DEFAULT '1',
  `allow_narration_in_each_ledger` tinyint(1) NOT NULL DEFAULT '0',
  `an_width_of_invoice_number` int DEFAULT NULL,
  `an_prefill_with_zero` tinyint(1) NOT NULL DEFAULT '0',
  `an_restart_applicable_from` date DEFAULT NULL,
  `an_restart_starting_number` int DEFAULT NULL,
  `an_restart_period` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `an_prefix_details` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `an_suffix_details` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `numbering_behaviour` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_voucher_type_company_name` (`company_id`,`name`)
) ENGINE=InnoDB AUTO_INCREMENT=27 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
